// Deno Edge Function — Poppins Monitor Agent.
// Rules first; model only when needs_prose + kill switch + window + daily cap.
// Auth: service role for cron, or JWT + active member for client session kick.

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.49.1';
import {
  buildCompactHouseholdContext,
  corsHeaders,
  jsonResponse,
  requireActiveMember,
} from '../_shared/poppins-auth.ts';
import {
  executePoppinsTool,
  type HouseholdSnapshotEdge,
} from '../_shared/execute-poppins-tool.ts';
import { getOpenAIPoppinsChatModel } from '../_shared/openai-models.ts';
import {
  buildMajordomoSystemPrompt,
  poppinsMonitorToolsAsOpenAIFunctions,
} from '../_shared/poppins-tools.ts';
import {
  applyTemplates,
  evaluateHouseholdRules,
  withinActiveWindow,
  type FiredMonitorRule,
} from '../_shared/monitor-rules.ts';
import {
  POPPINS_MONITOR_ACTIVE_HOURS,
  POPPINS_MONITOR_MAX_ROUNDS,
  POPPINS_MONITOR_MODEL_CALLS_PER_DAY,
  isMonitorModelEnabled,
} from '../_shared/openai-rates.ts';
import { recordAiUsageEvent, usageFromOpenAIPayload } from '../_shared/ai-usage.ts';

type Snapshot = HouseholdSnapshotEdge;

function serviceClient() {
  const url = Deno.env.get('SUPABASE_URL')!;
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  return createClient(url, key);
}

function isServiceRole(req: Request) {
  const auth = req.headers.get('Authorization') ?? '';
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '';
  return Boolean(serviceKey) && auth === `Bearer ${serviceKey}`;
}

async function writeRecommendation(
  supabase: ReturnType<typeof serviceClient>,
  householdId: string,
  title: string,
  detail: string,
  tone = 'cyan'
) {
  await supabase.from('ai_recommendations').insert({
    household_id: householdId,
    title,
    detail,
    tone,
    status: 'active',
  });
}

async function countMonitorModelCallsToday(
  supabase: ReturnType<typeof serviceClient>,
  householdId: string,
  timezone: string
): Promise<number> {
  // Count monitor rows since local midnight (approx via UTC day bucket + TZ offset not required for soft cap).
  const start = new Date();
  try {
    const local = new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone || 'America/Toronto',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    }).format(start);
    // en-CA → YYYY-MM-DD
    const dayStart = new Date(`${local}T00:00:00`);
    const { count, error } = await supabase
      .from('ai_usage_events')
      .select('id', { count: 'exact', head: true })
      .eq('household_id', householdId)
      .eq('kind', 'monitor')
      .gte('occurred_at', dayStart.toISOString());
    if (error) {
      console.warn('countMonitorModelCallsToday', error.message);
      return 0;
    }
    return count ?? 0;
  } catch (error) {
    console.warn('countMonitorModelCallsToday failed', error);
    return 0;
  }
}

async function runToolLoop(
  openaiKey: string,
  household: Snapshot,
  metrics: Record<string, unknown>,
  householdId: string,
  maxRounds: number
) {
  const context = buildCompactHouseholdContext(household as Record<string, unknown>);
  const desk = household.desk ?? {};
  const profileId = (household.majordomoProfileId as string | undefined) ?? 'poppins';
  // Shrunk prompt: desk + compact context only (no redundant full dumps).
  const messages: Array<Record<string, unknown>> = [
    {
      role: 'system',
      content:
        `${buildMajordomoSystemPrompt(profileId)}\n` +
        `Desk: ${JSON.stringify(desk).slice(0, 1800)}\n` +
        `Context: ${JSON.stringify({ metrics, ...context }).slice(0, 2800)}`,
    },
    {
      role: 'user',
      content:
        'Run a Monitor pass. Prefer notifying over mutating. Call list_holidays before any nudge. Propose at most 2 concrete actions from the desk. Then summarize.',
    },
  ];

  const effects: Array<Record<string, unknown>> = [];
  let summary = '';
  let totalIn = 0;
  let totalOut = 0;
  let totalCached = 0;
  const model = getOpenAIPoppinsChatModel();
  const tools = poppinsMonitorToolsAsOpenAIFunctions();

  for (let step = 0; step < maxRounds; step++) {
    const completion = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${openaiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model,
        messages,
        tools,
        tool_choice: step === 0 ? 'required' : 'auto',
      }),
    });

    const payload = await completion.json();
    const usage = usageFromOpenAIPayload(payload);
    totalIn += usage.inputTokens;
    totalOut += usage.outputTokens;
    totalCached += usage.cachedInputTokens;

    const message = payload.choices?.[0]?.message;
    if (!message) break;

    messages.push(message);
    const toolCalls = message.tool_calls ?? [];
    if (!toolCalls.length) {
      summary = String(message.content ?? '');
      break;
    }

    for (const call of toolCalls) {
      const name = call.function?.name ?? '';
      let args: Record<string, unknown> = {};
      try {
        args = JSON.parse(call.function?.arguments ?? '{}');
      } catch {
        args = {};
      }
      const result = executePoppinsTool(name, args, household, metrics);
      effects.push({ tool: name, args, result });
      messages.push({
        role: 'tool',
        tool_call_id: call.id,
        content: JSON.stringify(result),
      });
    }
  }

  await recordAiUsageEvent({
    householdId,
    clientKey: `monitor-${householdId}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    kind: 'monitor',
    model,
    inputTokens: totalIn,
    outputTokens: totalOut,
    cachedInputTokens: totalCached,
    surface: 'poppins-monitor',
    mode: 'rules_gated',
  });

  return { effects, summary };
}

async function persistEffects(
  supabase: ReturnType<typeof serviceClient>,
  householdId: string,
  effects: Array<Record<string, unknown>>
) {
  const actions: Array<{
    kind: string;
    label: string;
    detail: string;
    data?: Record<string, unknown>;
  }> = [];

  for (const effect of effects) {
    const result = effect.result as Record<string, unknown>;
    const tool = String(effect.tool);

    if (result?.notification && typeof result.notification === 'object' && !result.skipped) {
      const n = result.notification as { title: string; body: string; data?: Record<string, unknown> };
      const planDraft = result.planDraft as Record<string, unknown> | undefined;
      actions.push({
        kind: tool === 'propose_plan' ? 'plan' : tool,
        label: n.title,
        detail: n.body,
        data: planDraft
          ? {
              dayLabel: planDraft.dayLabel,
              planTitle: planDraft.title,
              planDetail: planDraft.detail,
              href: '/create-itinerary',
            }
          : n.data,
      });
    }

    if (result?.recommendation && typeof result.recommendation === 'object') {
      const r = result.recommendation as { title: string; detail: string; tone?: string };
      await writeRecommendation(supabase, householdId, r.title, r.detail, r.tone ?? 'cyan');
      actions.push({ kind: tool, label: r.title, detail: r.detail });
    }

    if (tool === 'scan_deals' && Array.isArray(result?.deals) && (result.deals as unknown[]).length) {
      const deals = result.deals as Array<{ title: string; store?: string }>;
      const top = deals.slice(0, 3);
      const body = top
        .map((d) => (d.store ? `${d.title} (${d.store})` : d.title))
        .join(' · ');
      await writeRecommendation(supabase, householdId, 'Still on the list', body, 'green');
      actions.push({ kind: 'deals', label: `Still needed: ${top.length}`, detail: body });
    }

    if (tool === 'list_overdue_tasks' && Array.isArray((result as { overdue?: unknown[] }).overdue)) {
      const overdue = (result as { overdue: Array<{ title?: string; assignee?: string }> }).overdue;
      for (const task of overdue.slice(0, 3)) {
        actions.push({
          kind: 'nudge',
          label: `${String(task.assignee ?? 'someone')} is late`,
          detail: String(task.title ?? 'Task'),
        });
      }
    }
  }

  return actions;
}

async function persistTemplateActions(
  supabase: ReturnType<typeof serviceClient>,
  householdId: string,
  rules: FiredMonitorRule[]
) {
  const actions = applyTemplates(rules);
  for (const action of actions) {
    const tone = String(action.data?.tone ?? 'cyan');
    await writeRecommendation(supabase, householdId, action.label, action.detail, tone);
  }
  return actions;
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const body = await req.json().catch(() => ({}));
    const householdId = body.householdId as string | undefined;
    const metrics = (body.metrics ?? {}) as Record<string, unknown>;
    const household = (body.household ?? {}) as Snapshot;
    let openaiKey = Deno.env.get('OPENAI_API_KEY');

    const cron = isServiceRole(req);
    if (!cron) {
      const auth = await requireActiveMember(req.headers.get('Authorization'), householdId);
      if (auth.error) return auth.error;
      // App Review 5.1.2(i): rules still run; the AI summary only with permission.
      if (!auth.aiConsent) openaiKey = undefined;
    } else if (!householdId) {
      return jsonResponse({ error: 'householdId required for cron invoke' }, 400);
    } else if (openaiKey) {
      // Scheduled run, no person attached: use the AI summary only if an admin of this
      // household has allowed Poppins to use OpenAI.
      const admin = serviceClient();
      const { data: admins } = await admin
        .from('household_members')
        .select('user_id')
        .eq('household_id', householdId)
        .eq('status', 'active')
        .in('role', ['owner', 'admin']);
      const ids = (admins ?? []).map((row: { user_id: string | null }) => row.user_id).filter(Boolean);
      const { data: consented } = ids.length
        ? await admin.from('profiles').select('id').in('id', ids).not('ai_consent_at', 'is', null).limit(1)
        : { data: [] };
      if (!consented?.length) openaiKey = undefined;
    }

    if (!householdId) {
      return jsonResponse({ error: 'householdId required' }, 400);
    }

    const supabase = serviceClient();
    const timezone =
      String(
        (household as { timezone?: string }).timezone ??
          (household as { timeZone?: string }).timeZone ??
          ''
      ).trim() || 'America/Toronto';

    // Prefer live notification_prefs from DB so Settings toggles reach the monitor.
    let householdForRules: Record<string, unknown> = { ...(household as Record<string, unknown>) };
    try {
      const { data: hhRow } = await supabase
        .from('households')
        .select('notification_prefs')
        .eq('id', householdId)
        .maybeSingle();
      if (hhRow?.notification_prefs && typeof hhRow.notification_prefs === 'object') {
        householdForRules = {
          ...householdForRules,
          notification_prefs: hhRow.notification_prefs,
          notificationPrefs: hhRow.notification_prefs,
        };
      }
    } catch (error) {
      console.warn('poppins-monitor prefs load', error);
    }

    const fired = evaluateHouseholdRules(householdForRules, metrics);
    if (!fired.length) {
      return jsonResponse({
        ok: true,
        householdId,
        summary: null,
        actions: [],
        effectCount: 0,
        source: 'rules_idle',
      });
    }

    const prose = fired.filter((r) => r.needsProse);
    const modelAllowed =
      Boolean(openaiKey) &&
      prose.length > 0 &&
      isMonitorModelEnabled() &&
      withinActiveWindow(timezone, POPPINS_MONITOR_ACTIVE_HOURS);

    let effects: Array<Record<string, unknown>> = [];
    let summary: string | null = null;
    let source = 'templates';

    if (modelAllowed) {
      const callsToday = await countMonitorModelCallsToday(supabase, householdId, timezone);
      if (callsToday < POPPINS_MONITOR_MODEL_CALLS_PER_DAY) {
        const loop = await runToolLoop(
          openaiKey!,
          household,
          metrics,
          householdId,
          POPPINS_MONITOR_MAX_ROUNDS
        );
        effects = loop.effects;
        summary = loop.summary || null;
        source = 'openai_gated';
      } else {
        source = 'templates_cap';
      }
    }

    let actions =
      effects.length > 0
        ? await persistEffects(supabase, householdId, effects)
        : await persistTemplateActions(supabase, householdId, fired);

    if (effects.length > 0 && prose.length === 0) {
      // Model path shouldn't run without prose; keep templates as well if empty actions.
      if (!actions.length) {
        actions = await persistTemplateActions(supabase, householdId, fired);
      }
    }

    return jsonResponse({
      ok: true,
      householdId,
      summary,
      actions,
      effectCount: effects.length || fired.length,
      source,
      rulesFired: fired.map((r) => r.kind),
      monitorModel: isMonitorModelEnabled() ? 'on' : 'off',
    });
  } catch (error) {
    return jsonResponse({ error: String(error) }, 500);
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.49.1';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

export function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function isSidekickRole(role: string | null | undefined) {
  return role === 'child' || role === 'sidekick';
}

/** Poppins is always 403 for Sidekicks — there is no household switch for it. */
export function requireNonSidekick(
  role: string | null | undefined,
  options?: { allowed?: boolean }
) {
  if (isSidekickRole(role) && !options?.allowed) {
    return jsonResponse({ error: 'Poppins is not available on this profile.' }, 403);
  }
  return null;
}

export async function requireActiveMember(
  authHeader: string | null,
  householdId: string | null | undefined
) {
  if (!authHeader) {
    return { error: jsonResponse({ error: 'Unauthorized' }, 401) };
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY')!;
  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authHeader } },
  });

  const {
    data: { user },
    error: userError,
  } = await userClient.auth.getUser();

  if (userError || !user) {
    return { error: jsonResponse({ error: 'Unauthorized' }, 401) };
  }

  if (!householdId) {
    return { error: jsonResponse({ error: 'householdId required' }, 400) };
  }

  const { data: membership, error: memberError } = await userClient
    .from('household_members')
    .select('id, role, status, display_name')
    .eq('household_id', householdId)
    .eq('user_id', user.id)
    .maybeSingle();

  if (memberError || !membership || membership.status !== 'active') {
    return { error: jsonResponse({ error: 'Active household membership required' }, 403) };
  }

  // Sidekicks never get Poppins, whatever the household row says.
  const sidekickBlock = requireNonSidekick(membership.role, { allowed: false });
  if (sidekickBlock) {
    return { error: sidekickBlock };
  }

  // App Review 5.1.2(i): nothing goes to OpenAI for a person who has not allowed it.
  const { data: profile } = await userClient
    .from('profiles')
    .select('ai_consent_at')
    .eq('id', user.id)
    .maybeSingle();
  const aiConsent = Boolean((profile as { ai_consent_at?: string | null } | null)?.ai_consent_at);

  return { user, membership, userClient, aiConsent };
}

/** The reply when a person has not allowed Poppins to use OpenAI. The app shows its consent sheet. */
export function aiConsentRequired() {
  return jsonResponse(
    { error: 'ai_consent_required', message: 'Allow Poppins to use OpenAI in the app first.' },
    403
  );
}

export function buildCompactHouseholdContext(household: Record<string, unknown> | null | undefined) {
  if (!household || typeof household !== 'object') {
    return {};
  }

  const tasks = Array.isArray(household.tasks) ? household.tasks : [];
  const groceries = Array.isArray(household.groceries) ? household.groceries : [];
  const events = Array.isArray(household.events) ? household.events : [];
  const members = Array.isArray(household.members) ? household.members : [];

  return {
    householdName: household.householdName ?? household.household_name,
    greetingName: household.greetingName ?? household.greeting_name,
    openTasks: tasks
      .filter((t: { status?: string }) => t.status !== 'Completed' && t.status !== 'completed')
      .slice(0, 8)
      .map((t: { title?: string; assignee?: string; due?: string; status?: string }) => ({
        title: t.title,
        assignee: t.assignee,
        due: t.due,
        status: t.status,
      })),
    missingGroceries: groceries
      .filter((g: { status?: string }) => g.status === 'Missing' || g.status === 'missing')
      .slice(0, 6)
      .map((g: { name?: string; category?: string }) => ({ name: g.name, category: g.category })),
    upcomingEvents: events.slice(0, 5).map((e: { title?: string; date?: string; time?: string }) => ({
      title: e.title,
      date: e.date,
      time: e.time,
    })),
    members: members
      .filter((m: { status?: string }) => m.status === 'active')
      .map((m: { name?: string; role?: string; weekXp?: number; xp?: number; streak?: number }) => ({
        name: m.name,
        role: m.role,
        weekXp: m.weekXp ?? m.week_xp,
        xp: m.xp,
        streak: m.streak,
      })),
  };
}

/** Shared tool executor for chat + monitor + voice-tool edge functions. */

import { isRiskyPoppinsTool, scanGroceryNeeds } from './poppins-tools.ts';
import { describeToolForPerson, eventChangeAction, taskChangeAction } from './tool-task-match.ts';

export type HouseholdSnapshotEdge = {
  tasks?: Array<Record<string, unknown>>;
  groceries?: Array<Record<string, unknown>>;
  events?: Array<Record<string, unknown>>;
  members?: Array<Record<string, unknown>>;
  rewards?: Array<Record<string, unknown>>;
  itineraries?: Array<Record<string, unknown>>;
  householdName?: string;
  greetingName?: string;
  desk?: Record<string, unknown>;
  rewardModel?: string;
  homeworkEnabled?: boolean;
  majordomoProfileId?: string;
};

export type ExecutePoppinsToolOptions = {
  forceRiskyConfirmation?: boolean;
};

function pendingConfirm(
  name: string,
  args: Record<string, unknown>,
  summary: string
): Record<string, unknown> {
  const id = `pc-${name}-${Date.now()}`;
  return {
    pending_confirmations: [
      {
        id,
        tool: name,
        args,
        summary,
      },
    ],
    ui_actions: [
      {
        type: 'confirm',
        confirmSummary: summary,
        confirmationIds: [id],
      },
    ],
    note: 'Awaiting user confirmation before executing.',
  };
}

const IUI_SCENES = [
  'thinking',
  'task_compose',
  'homework_compose',
  'calendar_zoom',
  'itinerary_stage',
  'grocery_add',
  'reward_mint',
  'place_save',
  'allowance_act',
  'ranks_peek',
  'memory_note',
  'list_peek',
  'member_pick',
  'confirm',
  'navigate_coach',
  'coach_steps',
  'task_done',
  'result_mark',
] as const;

function isAssignSurfaceRoute(route: string) {
  return route.includes('assign-task') || route.includes('create-task');
}

function isGrocerySurfaceRoute(route: string) {
  return (
    route.includes('groceries') ||
    route.includes('shopping-mode') ||
    route.includes('grocery-browse')
  );
}

function peekAction(
  rows: Array<Record<string, unknown>>,
  thinkingLine: string
) {
  return {
    type: 'list_peek',
    thinkingLine,
    rows: rows.slice(0, 3).map((row) => ({
      id: row.id,
      title: row.title ?? row.name,
      assignee: row.assignee ?? row.responsible,
    })),
  };
}

export function executePoppinsTool(
  name: string,
  args: Record<string, unknown>,
  household: HouseholdSnapshotEdge,
  metrics: Record<string, unknown>,
  options: ExecutePoppinsToolOptions = {}
): Record<string, unknown> {
  const tasks = household.tasks ?? [];
  const groceries = household.groceries ?? [];
  const events = household.events ?? [];
  const members = household.members ?? [];
  const rewards = household.rewards ?? [];
  const itineraries = household.itineraries ?? [];

  // Changes to an existing task or event show their own card (Delete / Keep it, or the move,
  // reassign or rename with a hold). They never become a raw confirmation.
  if (name === 'delete_task' || name === 'update_task') {
    const action = taskChangeAction(name, args, tasks as unknown as Array<Record<string, unknown>>);
    return {
      ui_actions: [action],
      note: action.taskId
        ? `On screen: ${String(action.change)} “${String(action.title)}”. The person confirms there.`
        : 'Several tasks or none matched — the person picks on screen.',
    };
  }
  if (name === 'delete_event' || name === 'delete_calendar_event') {
    const action = eventChangeAction(args, events as unknown as Array<Record<string, unknown>>);
    if (!action) return { error: 'event_not_found' };
    return { ui_actions: [action], note: `On screen: remove “${String(action.title)}”. The person confirms there.` };
  }

  if (options.forceRiskyConfirmation && isRiskyPoppinsTool(name)) {
    return pendingConfirm(name, args, describeToolForPerson(name, args));
  }

  switch (name) {
    case 'list_overdue_tasks': {
      const overdue = tasks.filter(
        (t) =>
          t.status === 'Overdue' ||
          t.status === 'overdue' ||
          /overdue|expired/i.test(String(t.due ?? ''))
      );
      const sliced = overdue.slice(0, 10);
      return { overdue: sliced, ui_actions: [peekAction(sliced, 'Overdue')] };
    }
    case 'list_tasks': {
      const limit = typeof args.limit === 'number' ? Math.min(20, Math.max(1, args.limit)) : 12;
      const assignee = args.assignee ? String(args.assignee).toLowerCase() : '';
      const status = args.status ? String(args.status).toLowerCase() : '';
      const open = tasks
        .filter((t) => t.status !== 'Done' && t.status !== 'Completed' && t.status !== 'done')
        .filter(
          (t) => !assignee || String(t.assignee ?? '').toLowerCase().includes(assignee)
        )
        .filter((t) => !status || String(t.status ?? '').toLowerCase().includes(status))
        .slice(0, limit);
      return { tasks: open, ui_actions: [peekAction(open, 'Open tasks')] };
    }
    case 'nudge_member': {
      const memberName = String(args.memberName ?? args.member_id ?? '');
      const away = members.some((m) => {
        const same = String(m.name ?? '').toLowerCase() === memberName.toLowerCase();
        return same && (m.away === true || m.awayFrom || m.away_from);
      });
      if (away) {
        return { skipped: true, reason: 'member_away', memberName };
      }
      return {
        action: 'nudge',
        memberName,
        taskId: args.taskId ?? args.related_task_id,
        reason: args.reason ?? args.message,
        notification: {
          title: 'Poppins · Nudge',
          body: `${memberName}: ${args.reason ?? args.message}`,
          data: { kind: 'nudge', taskId: args.taskId },
        },
      };
    }
    case 'assess_xp_fairness': {
      const active = members.filter(
        (m) => m.status === 'active' && m.role !== 'guest' && m.role !== 'shared-device'
      );
      const sorted = [...active].sort(
        (a, b) => Number(b.weekXp ?? b.week_xp ?? 0) - Number(a.weekXp ?? a.week_xp ?? 0)
      );
      if (sorted.length < 2) return { gap: 0, recommendation: null };
      const top = sorted[0]!;
      const bottom = sorted[sorted.length - 1]!;
      const gap =
        Number(top.weekXp ?? top.week_xp ?? 0) - Number(bottom.weekXp ?? bottom.week_xp ?? 0);
      const detail = `${top.name} earned ${top.weekXp ?? top.week_xp ?? 0} XP this week vs ${bottom.name}'s ${bottom.weekXp ?? bottom.week_xp ?? 0}. Consider rebalancing tasks.`;
      return {
        gap,
        top: { name: top.name, weekXp: top.weekXp ?? top.week_xp ?? 0 },
        bottom: { name: bottom.name, weekXp: bottom.weekXp ?? bottom.week_xp ?? 0 },
        recommendation: gap >= 40 ? { title: 'Balance weekly XP', detail, tone: 'amber' } : null,
      };
    }
    case 'award_completion_xp': {
      return {
        action: 'award_completion_xp',
        taskId: args.taskId,
        note: 'XP awards are owned by the app on verified completion — Poppins only confirms.',
      };
    }
    case 'scan_deals': {
      const groceryNames = groceries
        .filter(
          (g) =>
            g.status === 'Missing' ||
            g.status === 'Low' ||
            g.status === 'missing' ||
            g.status === 'low'
        )
        .map((g) => String(g.name ?? ''));
      const categories = Array.isArray(args.categories) ? (args.categories as string[]) : undefined;
      return { deals: scanGroceryNeeds(groceryNames, categories) };
    }
    case 'list_groceries':
    case 'get_grocery_gaps': {
      const status = args.status ? String(args.status) : '';
      const filtered = groceries.filter((g) => {
        if (!status || status === 'any') {
          return g.status === 'Missing' || g.status === 'Low' || !status;
        }
        return String(g.status) === status;
      });
      return {
        groceries: filtered.slice(0, 30).map((g) => ({
          id: g.id,
          name: g.name,
          status: g.status,
          category: g.category,
        })),
      };
    }
    case 'add_grocery':
    case 'add_grocery_item': {
      const groceryName = String(args.name ?? '').trim();
      if (!groceryName) return { error: 'name_required' };
      const lane = args.lane === 'clothing' ? 'clothing' : undefined;
      const releaseDate = args.releaseDate ? String(args.releaseDate) : undefined;
      const ui_actions: Array<Record<string, unknown>> = [
        {
          type: 'add_grocery',
          name: groceryName,
          category: args.category ? String(args.category) : lane === 'clothing' ? 'Clothing' : undefined,
          lane,
          status: args.status ? String(args.status) : 'Missing',
        },
      ];
      if (releaseDate) {
        ui_actions.push({
          type: 'create_calendar_event',
          title: `${groceryName} drop`,
          date: releaseDate,
        });
      }
      return {
        ui_actions,
        note: `Staged add ${lane === 'clothing' ? 'shopping' : 'grocery'}: ${groceryName}`,
      };
    }
    case 'set_grocery_status':
    case 'update_grocery_status': {
      return {
        ui_actions: [
          {
            type: 'set_grocery_status',
            itemId: args.item_id ?? args.itemId,
            name: String(args.name ?? ''),
            status: String(args.status ?? 'Purchased'),
          },
        ],
      };
    }
    case 'read_calendar':
    case 'get_calendar_agenda': {
      const limit =
        typeof args.days === 'number'
          ? Math.min(14, Math.max(1, args.days))
          : typeof args.days_ahead === 'number'
            ? Math.min(14, Math.max(1, args.days_ahead))
            : 7;
      return {
        events: events.slice(0, limit),
        ui_actions: [peekAction(events.slice(0, 3), 'Upcoming')],
      };
    }
    case 'list_holidays':
    case 'get_recess_status': {
      const away = members.filter((m) => m.away === true || m.awayFrom || m.away_from);
      return {
        holidays: away.map((m) => ({
          name: m.name,
          awayFrom: m.awayFrom ?? m.away_from,
          awayTo: m.awayTo ?? m.away_to,
        })),
      };
    }
    case 'propose_plan': {
      const title = String(args.title ?? 'Proposed plan');
      const detail = String(args.detail ?? '');
      const dayLabel = args.dayLabel ? String(args.dayLabel) : undefined;
      return {
        recommendation: {
          title,
          detail: dayLabel ? `${detail} · ${dayLabel}` : detail,
          tone: 'cyan',
        },
        notification: {
          title: 'Poppins · Plan suggestion',
          body: detail || title,
          data: {
            kind: 'propose_plan',
            dayLabel,
            planTitle: title,
            planDetail: detail,
          },
        },
        planDraft: {
          title,
          detail,
          dayLabel,
          href: '/create-itinerary',
        },
        ui_actions: [{ type: 'create_itinerary', title }],
      };
    }
    case 'ask_for_info': {
      const memberName = String(args.memberName ?? args.member_id ?? 'member');
      return {
        notification: {
          title: 'Poppins needs a detail',
          body: `${memberName}, ${args.question}`,
          data: { kind: 'ask_for_info' },
        },
      };
    }
    case 'remember_house_fact': {
      const kindRaw = String(args.kind ?? 'note');
      const kind =
        kindRaw === 'like' || kindRaw === 'dislike' || kindRaw === 'routine' || kindRaw === 'note'
          ? kindRaw
          : 'note';
      const text = String(args.text ?? '').trim();
      const subject = String(args.subject ?? 'house').trim() || 'house';
      if (!text) return { error: 'empty_fact' };
      if (/\b(password|ssn|social security|medical|diagnosis|prescription|home address)\b/i.test(text)) {
        return pendingConfirm(name, args, 'That sounds private — confirm before I remember it.');
      }
      return {
        remembered: true,
        fact: { kind, subject, text, source: 'spoken' },
        ui_actions: [{ type: 'remember_house_fact', kind, subject, text }],
      };
    }
    case 'list_members': {
      const active = members
        .filter((m) => m.status === 'active')
        .map((m) => ({
          id: m.id,
          name: m.name,
          role: m.role,
          weekXp: m.weekXp ?? m.week_xp ?? 0,
        }));
      return {
        members: active,
        ui_actions: [
          {
            type: 'member_pick',
            faces: active.slice(0, 3).map((m) => ({ id: m.id, name: m.name })),
          },
        ],
      };
    }
    case 'list_rewards': {
      const rankRows = members
        .filter((m) => {
          const status = String(m.status ?? 'active');
          const role = String(m.role ?? '');
          return status === 'active' && role !== 'guest' && role !== 'shared-device';
        })
        .slice()
        .sort((a, b) => Number(b.weekXp ?? b.week_xp ?? 0) - Number(a.weekXp ?? a.week_xp ?? 0))
        .slice(0, 5)
        .map((m, i) => ({
          id: m.id,
          title: `${i + 1}. ${String(m.name ?? 'Member')}`,
          detail: `${Number(m.weekXp ?? m.week_xp ?? 0)} XP this week`,
        }));
      return {
        rewards: rewards.slice(0, 20).map((r) => ({
          id: r.id,
          title: r.title ?? r.name,
          cost: r.cost,
        })),
        ui_actions: [{ type: 'ranks_peek', rows: rankRows }],
      };
    }
    case 'search_house_rules': {
      return {
        hits: [],
        note: 'House rules search is resolved on-device; ask the user to open House Rules if needed.',
        query: String(args.query ?? ''),
      };
    }
    case 'get_pending_approvals': {
      return {
        pendingProofs: tasks
          .filter((t) => /proof|pending.?review|awaiting/i.test(String(t.status ?? '')))
          .slice(0, 10),
        pendingRedemptions: rewards.filter((r) => r.pending === true).slice(0, 10),
        pendingAllowances: [],
      };
    }
    case 'get_briefing_snapshot': {
      return {
        householdName: household.householdName,
        greetingName: household.greetingName,
        desk: household.desk ?? {},
        metrics,
        openTasks: metrics.openTasks,
        upcomingEvents: events.slice(0, 5),
      };
    }
    case 'get_unread_notifications': {
      return {
        notifications: [],
        note: 'Unread notifications are resolved by the live app session.',
      };
    }
    case 'list_itineraries': {
      const limit = typeof args.limit === 'number' ? Math.min(20, Math.max(1, args.limit)) : 8;
      return { itineraries: itineraries.slice(0, limit) };
    }
    case 'get_smart_home_state': {
      return { linked: false, scenes: [], note: 'Smart home is optional.' };
    }
    case 'create_task_draft':
    case 'assign_task':
    case 'create_task': {
      return {
        ui_actions: [
          {
            type: 'create_task_draft',
            title: String(args.title ?? ''),
            assignee: args.assignee ?? args.assignee_id,
            due: args.due ?? args.due_at,
            detail: args.detail ?? args.description,
            category: args.category,
            libraryTaskId: args.libraryTaskId ?? args.library_task_id,
            taskQuery: args.taskQuery ?? args.task_query,
          },
        ],
        note: 'HOLD silence creates the task. Never say draft.',
      };
    }
    case 'update_task': {
      return {
        ui_actions: [
          {
            type: 'update_task',
            taskId: args.taskId ?? args.task_id,
            patch: args,
          },
        ],
      };
    }
    case 'complete_task': {
      const taskId = String(args.taskId ?? args.task_id ?? '');
      const title = String(args.title ?? '').toLowerCase();
      const match =
        tasks.find((t) => String(t.id) === taskId) ||
        tasks.find((t) => title && String(t.title ?? '').toLowerCase().includes(title));
      if (!match) return { error: 'task_not_found' };
      return {
        ui_actions: [{ type: 'complete_task', taskId: match.id, title: match.title }],
        note: `Staged complete: ${match.title}`,
      };
    }
    case 'create_calendar_event': {
      return {
        ui_actions: [
          {
            type: 'create_calendar_event',
            title: String(args.title ?? ''),
            date: args.date ?? args.starts_at,
            time: args.time,
            location: args.location,
            notes: args.notes,
          },
        ],
        note: 'Staged event on the IUI stage. HOLD silence commits.',
      };
    }
    case 'create_itinerary': {
      const stopsRaw = Array.isArray(args.stops) ? args.stops : [];
      const stops = stopsRaw.slice(0, 10).map((row) => {
        const s = row && typeof row === 'object' ? (row as Record<string, unknown>) : {};
        return {
          label: String(s.label ?? ''),
          placeQuery: s.placeQuery ?? s.place_query,
          address: s.address,
          time: s.time,
          kind: s.kind ?? 'other',
          notes: s.notes,
        };
      }).filter((s) => s.label.trim());
      const title = String(args.title ?? (stops[0]?.label || 'Trip'));
      return {
        ui_actions: [
          {
            type: 'create_itinerary',
            title,
            date: args.date,
            startsAt: args.startsAt ?? args.starts_at,
            notes: args.notes,
            stops: stops.length
              ? stops
              : [{ label: title, kind: 'other' }],
          },
        ],
        note: 'Staged multi-stop itinerary on the IUI stage. HOLD silence commits.',
      };
    }
    case 'resolve_place': {
      const query = String(args.query ?? '').trim();
      const places = Array.isArray(household.savedPlaces)
        ? (household.savedPlaces as Array<Record<string, unknown>>)
        : Array.isArray(household.places)
          ? (household.places as Array<Record<string, unknown>>)
          : [];
      const q = query.toLowerCase();
      const saved = places.find((p) => {
        const name = String(p.name ?? p.label ?? '').toLowerCase();
        const kind = String(p.kind ?? '').toLowerCase();
        return name === q || kind === q || name.includes(q);
      });
      if (saved) {
        return {
          place: {
            label: String(saved.name ?? saved.label ?? query),
            address: String(saved.address ?? ''),
            lat: saved.lat,
            lng: saved.lng,
            source: 'saved',
          },
        };
      }
      return {
        place: null,
        query,
        note: 'No saved place match. Client may geocode; do not invent an address.',
      };
    }
    case 'list_saved_places': {
      const places = Array.isArray(household.savedPlaces)
        ? (household.savedPlaces as Array<Record<string, unknown>>)
        : Array.isArray(household.places)
          ? (household.places as Array<Record<string, unknown>>)
          : [];
      return {
        places: places.slice(0, 40).map((p) => ({
          id: p.id,
          name: p.name ?? p.label,
          kind: p.kind,
          address: p.address,
          lat: p.lat,
          lng: p.lng,
        })),
      };
    }
    case 'advance_itinerary_stop': {
      return {
        ui_actions: [
          {
            type: 'advance_itinerary_stop',
            itineraryId: args.itineraryId ?? args.itinerary_id,
          },
        ],
      };
    }
    case 'claim_reward': {
      return {
        ui_actions: [
          {
            type: 'claim_reward',
            rewardName: args.rewardName,
            rewardId: args.reward_id ?? args.rewardId,
          },
        ],
      };
    }
    case 'navigate_to': {
      const route = String(args.route ?? '');
      const openEditor = args.openEditor === true;
      if (isAssignSurfaceRoute(route) && !openEditor) {
        return {
          ui_actions: [
            {
              type: 'create_task_draft',
              title: args.title ? String(args.title) : '',
              assignee: args.assignee,
              category: args.category,
            },
          ],
          note: 'HOLD silence creates the task instead of opening the full screen.',
        };
      }
      if (isGrocerySurfaceRoute(route) && !openEditor) {
        const groceryName = String(args.name ?? args.title ?? '').trim();
        if (groceryName) {
          return {
            ui_actions: [{ type: 'add_grocery', name: groceryName }],
            note: `Staged add grocery: ${groceryName}`,
          };
        }
        return {
          ui_actions: [
            {
              type: 'present_ui_scene',
              scene: 'thinking',
              payload: { thinkingLine: 'What should I add?' },
            },
          ],
        };
      }
      return {
        ui_actions: [
          {
            type: 'navigate',
            route,
            openEditor: openEditor || undefined,
            reason: args.reason ?? 'Opening that now.',
            params: args.params,
          },
        ],
      };
    }
    case 'present_ui_scene': {
      const scene = String(args.scene ?? 'thinking');
      if (!(IUI_SCENES as readonly string[]).includes(scene)) {
        return { error: 'unknown_scene', scene, allowed: IUI_SCENES };
      }
      return {
        ui_actions: [
          {
            type: 'present_ui_scene',
            scene,
            payload: args.payload && typeof args.payload === 'object' ? args.payload : {},
            commit: args.commit,
          },
        ],
      };
    }
    case 'delete_task':
    case 'clear_grocery_list':
    case 'wipe_grocery_list':
    case 'delete_event':
    case 'delete_calendar_event':
    case 'approve_redemption':
    case 'reject_redemption':
    case 'approve_allowance':
    case 'reject_allowance':
    case 'grant_allowance': {
      const memberName = String(args.memberName ?? args.member_name ?? '').trim();
      const amountRaw = args.amount ?? args.amountLabel ?? args.amount_label;
      const amountLabel =
        typeof amountRaw === 'number'
          ? `$${amountRaw}`
          : String(amountRaw ?? '').trim() || 'Allowance';
      if (!memberName) {
        return pendingConfirm(name, args, describeToolForPerson(name, args));
      }
      return {
        ui_actions: [
          {
            type: 'grant_allowance',
            memberName,
            memberId: args.memberId ?? args.member_id,
            amountLabel,
            amountXp: typeof args.amountXp === 'number' ? args.amountXp : undefined,
            note: args.note ? String(args.note) : undefined,
            kind: args.kind === 'hold' || args.kind === 'payout' ? args.kind : 'grant',
          },
        ],
        note: 'Staged allowance on the IUI stage — confirm required.',
      };
    }
    case 'remove_member':
    case 'change_member_role':
    case 'mass_reassign_tasks':
    case 'recess_everyone':
    case 'run_smart_home_scene':
    case 'update_reward_model': {
      return pendingConfirm(name, args, describeToolForPerson(name, args));
    }
    case 'ui_confirm_pending': {
      return {
        acknowledged: true,
        confirmationIds: Array.isArray(args.confirmationIds)
          ? args.confirmationIds
          : Array.isArray(args.confirmation_ids)
            ? args.confirmation_ids
            : [],
      };
    }
    case 'end_session': {
      return {
        session_control: 'end',
        reason: args.reason ? String(args.reason) : 'done',
        farewell: args.farewell,
      };
    }
    default:
      return { error: `Unknown tool: ${name}`, metrics };
  }
}

export function effectsToClientActions(
  effects: Array<{ tool: string; args: Record<string, unknown>; result: Record<string, unknown> }>
) {
  const now = new Date().toISOString();
  const actions: Array<{
    id: string;
    kind: string;
    label: string;
    detail: string;
    createdAt: string;
    data?: Record<string, unknown>;
  }> = [];

  for (const effect of effects) {
    const { tool, args, result } = effect;
    if (tool === 'propose_plan' || result.planDraft) {
      const draft = (result.planDraft ?? {}) as Record<string, unknown>;
      actions.push({
        id: `chat-plan-${now}-${actions.length}`,
        kind: 'plan',
        label: String(draft.title ?? args.title ?? 'Proposed plan'),
        detail: String(draft.detail ?? args.detail ?? ''),
        createdAt: now,
        data: {
          dayLabel: draft.dayLabel ?? args.dayLabel,
          planTitle: draft.title ?? args.title,
          planDetail: draft.detail ?? args.detail,
          href: '/create-itinerary',
        },
      });
      continue;
    }
    if (tool === 'nudge_member') {
      if (result.skipped) {
        actions.push({
          id: `chat-nudge-skip-${now}-${actions.length}`,
          kind: 'holiday',
          label: `Skipped nudge · ${args.memberName ?? 'member'} away`,
          detail: 'Poppins does not nudge members on holiday.',
          createdAt: now,
        });
      } else {
        actions.push({
          id: `chat-nudge-${now}-${actions.length}`,
          kind: 'nudge',
          label: `Nudged ${args.memberName ?? 'member'}`,
          detail: String(args.reason ?? args.message ?? ''),
          createdAt: now,
        });
      }
      continue;
    }
    if (tool === 'assess_xp_fairness') {
      const rec = result.recommendation as { detail?: string } | null;
      actions.push({
        id: `chat-xp-${now}-${actions.length}`,
        kind: 'xp_fairness',
        label: 'Assessed XP fairness',
        detail: rec?.detail ?? `Gap ${String(result.gap ?? 0)} XP this week`,
        createdAt: now,
      });
      continue;
    }
    if (tool === 'scan_deals') {
      const deals = Array.isArray(result.deals) ? result.deals : [];
      actions.push({
        id: `chat-deals-${now}-${actions.length}`,
        kind: 'deals',
        label: deals.length ? `Found ${deals.length} deals` : 'Scanned deals',
        detail: deals.length
          ? deals
              .slice(0, 3)
              .map((d: { title?: string; store?: string }) => `${d.title} @ ${d.store}`)
              .join(' · ')
          : 'No strong matches right now',
        createdAt: now,
      });
      continue;
    }
    if (tool === 'list_overdue_tasks') {
      const overdue = Array.isArray(result.overdue) ? result.overdue : [];
      actions.push({
        id: `chat-overdue-${now}-${actions.length}`,
        kind: 'monitor',
        label: overdue.length ? `${overdue.length} overdue` : 'No overdue tasks',
        detail: overdue
          .slice(0, 3)
          .map((t: { title?: string; assignee?: string }) => `${t.title} · ${t.assignee}`)
          .join(' · '),
        createdAt: now,
      });
      continue;
    }
    if (result.pending_confirmations) {
      actions.push({
        id: `chat-pending-${now}-${actions.length}`,
        kind: 'monitor',
        label: `Needs confirmation · ${tool}`,
        detail: String(args.title ?? args.name ?? args.memberName ?? ''),
        createdAt: now,
        data: { pending_confirmations: result.pending_confirmations },
      });
      continue;
    }
    if (tool === 'end_session') {
      actions.push({
        id: `chat-end-${now}-${actions.length}`,
        kind: 'monitor',
        label: 'Ended voice session',
        detail: String(args.reason ?? result.reason ?? ''),
        createdAt: now,
      });
    }
  }

  return actions;
}

